sealed interface AppError {
    val message: String
}
sealed interface Retryable          // cross-cutting marker
sealed interface UserFacing

data class NetworkError(override val message: String) : AppError, Retryable
data class RateLimited(override val message: String, val retryAfter: Duration) : AppError, Retryable, UserFacing
data class ValidationError(override val message: String, val field: String) : AppError, UserFacing
data class Unknown(override val message: String, val cause: Throwable) : AppError

// Handle by capability, not just by concrete type
fun handle(error: AppError) {
    if (error is Retryable) scheduleRetry(error)
    if (error is UserFacing) showSnackbar(error.message)
}

// Exhaustive — no `else`, so a new variant breaks the build here on purpose
fun icon(error: AppError): Int = when (error) {
    is NetworkError    -> R.drawable.ic_offline
    is RateLimited     -> R.drawable.ic_clock
    is ValidationError -> R.drawable.ic_warning
    is Unknown         -> R.drawable.ic_error
}

open class Animal
class Dog : Animal()

fun Animal.speak() = "generic noise"
fun Dog.speak() = "woof"

val pet: Animal = Dog()
println(pet.speak())      // "generic noise" — NOT "woof"

// Member always wins over an extension
class Cup { fun fill() = "member" }
fun Cup.fill() = "extension"      // compiler warns: shadowed by a member
println(Cup().fill())              // "member"

// Nullable receiver — no ?. needed at the call site
fun String?.orPlaceholder(): String = if (isNullOrBlank()) "—" else this
val label: String = user.nickname.orPlaceholder()

// The pattern every ViewModel has been writing:
class OldViewModel : ViewModel() {
    private val _state = MutableStateFlow(UiState.Loading)
    val state: StateFlow<UiState> = _state.asStateFlow()

    fun load() { _state.value = UiState.Content(...) }
}

// With explicit backing fields — one property, two types
class NewViewModel : ViewModel() {
    val state: StateFlow<UiState>
        field = MutableStateFlow(UiState.Loading)   // mutable inside

    fun load() { state.value = UiState.Content(...) }  // public sees StateFlow
}

sealed interface DataError {
    data object Offline : DataError
    data object NotFound : DataError
    data class RateLimited(val retryAfter: Duration) : DataError
    data class Unexpected(val cause: Throwable) : DataError
}

sealed interface Outcome<out T> {
    data class Success<T>(val value: T) : Outcome<T>
    data class Failure(val error: DataError) : Outcome<Nothing>
}

// A cancellation-safe replacement for runCatching
suspend inline fun <T> safeCall(block: () -> T): Outcome<T> = try {
    Outcome.Success(block())
} catch (e: CancellationException) {
    throw e                                  // never swallow cancellation
} catch (e: IOException) {
    Outcome.Failure(DataError.Offline)
} catch (e: HttpException) {
    Outcome.Failure(
        when (e.code()) {
            404 -> DataError.NotFound
            429 -> DataError.RateLimited(e.retryAfter())
            else -> DataError.Unexpected(e)
        }
    )
}

// The UI is forced to handle every case
fun render(outcome: Outcome<User>) = when (outcome) {
    is Outcome.Success -> showUser(outcome.value)
    is Outcome.Failure -> when (val e = outcome.error) {
        DataError.Offline      -> showOfflineBanner()
        DataError.NotFound     -> showEmptyState()
        is DataError.RateLimited -> showRetryIn(e.retryAfter)
        is DataError.Unexpected  -> { report(e.cause); showGenericError() }
    }
}

@DslMarker
annotation class FixtureDsl

@FixtureDsl
class UserBuilder {
    var name: String = "Test User"
    var premium: Boolean = false
    private val orders = mutableListOf<Order>()

    fun order(block: OrderBuilder.() -> Unit) {
        orders += OrderBuilder().apply(block).build()
    }

    fun build() = User(name, premium, orders.toList())
}

@FixtureDsl
class OrderBuilder {
    var total: Int = 0
    fun build() = Order(total)
}

fun user(block: UserBuilder.() -> Unit): User = UserBuilder().apply(block).build()

// Readable, type-safe test fixtures
val ada = user {
    name = "Ada"
    premium = true
    order { total = 4_200 }
    order { total = 999 }
    // name = ...   <- inside `order`, @DslMarker blocks reaching the outer builder
}
